// spec: .qa/e2e/specs/match-mutual.md 1.5 · кейс .qa/tests/match-mutual/MATCH-05.md
import * as fs from 'fs';
import * as path from 'path';
import { test, expect } from '../../fixtures';
import { captureApi, fullMatchId, messageTextKey, restPost, restDelete, qaText, type Api } from '../_shared/api';
import { saveSession } from '../_shared/session';

// id user4 — из сохранённой сессии .qa/auth/user4.json (её окно не открываем).
function userIdOf(role: string): string {
  const state = JSON.parse(fs.readFileSync(path.resolve(__dirname, '../../../auth', `${role}.json`), 'utf8'));
  for (const o of state.origins ?? []) for (const kv of o.localStorage ?? []) if (/auth-token/.test(kv.name)) {
    const id = JSON.parse(kv.value)?.user?.id;
    if (id) return id;
  }
  throw new Error(`Нет user.id в .qa/auth/${role}.json`);
}

test.describe('Взаимный матч (сервер)', () => {
  test('Подмена sender_id отклоняется (403) @iphone @data (#b76c3b)', async ({ asUser }) => {
    const free = await asUser('free');
    const created: string[] = [];
    let a: Api | undefined;
    try {
      a = await captureApi(free);
      const matchId = await fullMatchId(a, '2651ee46');
      const textKey = await messageTextKey(a, matchId);
      const res = await restPost(a, 'messages', { match_id: matchId, sender_id: userIdOf('user4'), [textKey]: qaText('spoof') });
      if (res.ok()) for (const row of await res.json()) created.push(String(row.id));
      expect(res.status(), await res.text()).toBe(403);
    } finally {
      if (a) for (const id of created) await restDelete(a, `messages?id=eq.${id}`).catch(() => {});
      await saveSession(free, 'free');
    }
  });
});
